"""Preserve supplied v3 cards and add the five missing first-visit scenes."""
from pathlib import Path
import zipfile,json,re,hashlib,sys
R=Path(__file__).resolve().parent.parent
if len(sys.argv)!=2:raise SystemExit('Usage: python supplement_environment_cards.py <directory-containing-updated-card-archives>')
source=Path(sys.argv[1])
out=R/'cards/environment';out.mkdir(parents=True,exist_ok=True)
original_hashes={}
with zipfile.ZipFile(source/'环境卡_修改版.zip') as z:
 for n in z.namelist():
  if n.endswith('.md'):
   raw=z.read(n);(out/Path(n).name).write_bytes(raw);original_hashes[Path(n).name]=hashlib.sha256(raw).hexdigest()
specs=[
 dict(file='10_狗儿家.md',id='SC10_GEJ',name='狗儿家',place='京郊农家住处，屋内与小院相接，家人可自由走动。',space='一间生活起居屋连小院。炕、灶和桌凳靠墙，中间留出交谈与走向院门的地方。',material='土地面、土墙、旧木桌凳、粗布被褥。',light='窗纸透进散光，院门带来较亮的一条光；夜里若点灯，只照到近处。',sound=['风擦窗纸','碗放在木桌上的轻响'],smell=['灶灰','旧柴'],temp='门边通风，炕边相对暖；具体天气随场次变化。',anchors=[('炕前','能看见屋中家人，靠炕的人并不自动拥有决定权。','room',3),('桌旁','放茶碗、听人说话，桌凳占地不能穿过。','room',2),('屋中','家人商量事情的空处，正常说话同屋可闻。','room',3),('低声交谈处','屋中相邻的两个独立站位；两人靠近后才能低声说。','room',2),('门内','可与屋里答话，也可看见小院。','room',2),('小院','屋里只见门口这一带，低声话不传入屋。','yard',3)],people='刘姥姥、狗儿、刘氏、板儿、青儿',opening='窗纸被风轻轻顶了一下，桌上的碗没有动。刘姥姥站在炕前，狗儿和刘氏留在屋中，两个孩子在近旁。',tensions=['屋小容易听见，家人却不一定愿意把难处说透。','桌凳能留住人坐下，门又提醒人还有外面可去。','家人彼此熟悉，商量办法时仍需等别人把话说完。'],scenario='秋尽冬初；家中衣食不足，但没有固定的求助结局。能否坐由角色选择和现有动作素材决定；家人可先开口；离场须说清去向。',exits=[('SC01_JM','院门，经城外道路到宁荣街','有人决定出门且实际走到出口')],props=['土炕','桌凳','茶碗','被褥','灶台','水缸','院门'],triggers=[('窗纸遇风','窗纸轻响，不强制任何人开口'),('有人跨过院门','更新室内外位置和可听范围')],palette='土黄与旧木色为主，青灰被褥点缀；不添加富贵陈设。'),
 dict(file='11_荣府后街.md',id='SC11_HJ',name='荣府后街',place='荣府后门外的小街与门内的一小段仆役巷道。',space='墙边摆摊担，中间留人走动；后门把街面与内巷分开。',material='磨旧砖石、墙灰、木摊架、竹编筐和粗布遮棚。',light='街面受天光，摊棚下较暗，门内的墙面反射少量散光。',sound=['摊担器物轻响','孩子脚步与交谈','街上来往声'],smell=['蒸面食','炉火'],temp='街口有风，棚下略能避风。',anchors=[('街口','从角门方向绕来，能看见后门及摊担。','street',3),('食物摊前','可看商品；摊担与炉子是固定障碍。','street',2),('玩具摊前','能看见摊上物件，不自动触发购买。','street',2),('孩子活动处','与摊位留开距离，街边的人可看见。','street',5),('后门外','询问或等待；门开时可看见内巷。','edge',3),('后门内巷','通向住处，转角后看不见大部分街面。','lane',3)],people='刘姥姥、板儿、引路孩童；其他孩子与摊贩仅在实际配置后加入',opening='门外的摊担靠着墙，竹筐挨着木架。几个脚步声从门口掠过，后门内露出一小段砖地。',tensions=['人多容易找到人，也容易把称呼叫混。','门敞着像是随时能进，进去后仍需知道要找谁。','摊上的物件吸引孩子，带路却需要把目光从物件上移开。'],scenario='进城后的某一时刻，由调度器填入来意和在场者。门外可以主动询问；是否带路由孩子回应决定。',exits=[('SC01_JM','沿后街原路绕回','人物选择返回'),('SC12_ZRZ','后门内巷','已确认要找的住处且获得可执行路线')],props=['摊担','竹筐','蒸笼','茶壶','玩具托盘','后门'],triggers=[('器物被取放','相应摊担发出轻响'),('人物转入内巷','街面普通话的可闻程度按声区规则重新计算')],palette='青灰砖墙、赭石摊架，布棚用褪色黄；少量玩具色不铺满街面。'),
 dict(file='12_周瑞妻子住处.md',id='SC12_ZRZ',name='周瑞妻子住处',place='荣府仆役居住区域的一处小院与起居屋；屋主是周瑞妻子。',space='门外一小块等候处，入门可到屋内坐谈，再由院门返回巷道。具体尺寸留给模型绑定。',material='砖地、灰墙、木桌椅、素布门帘。',light='院中天光较亮，屋内光从门与窗进入，门帘落下后明暗分开。',sound=['院门开合','斟茶','巷道远处脚步'],smell=['茶水','炭灰'],temp='院内通风，屋内可避冷。',anchors=[('院门外','来客可呼唤，屋内不自动听清低语。','lane',3),('院门内','主人迎客或送客的位置。','court',3),('屋门边','可以通报，不能挡住出入。','edge',2),('桌前客位','主人示意后可以落座；不强制出现坐姿。','room',2),('主人侧位','与客位能相对交谈。','room',2),('屋内低语处','两个独立近距站位，远处的人只能看到靠近动作。','room',2)],people='周瑞妻子；来访者由调度器填入，可包括刘姥姥、板儿及通报丫鬟',opening='门帘落在半明半暗的屋门前，桌上留着茶碗。院外若有人呼唤，声音先到门边。',tensions=['住处不大，却能让求人的话暂时离开外人的耳朵。','主人愿意招呼，不等于替府中主事者作决定。','茶能让人慢慢说，等候的消息又催人起身。'],scenario='来意、熟悉程度与此前答复从上下文读取。来客可自报姓名，是否入屋、坐下由主人回应；通报不自动成功。',exits=[('SC11_HJ','院门及仆役巷道','可自行离开'),('SC13_DT','巷道前往候见倒厅','需要实际获得引见或通行条件')],props=['院门','门帘','桌椅','茶壶','茶碗'],triggers=[('门帘被掀开','门边光线变化并发出布帘轻响'),('茶碗被放下','桌上传出轻响；不替人物解释动机')],palette='旧木、暖灰、低饱和青绿；整洁而不按小姐院落配置陈设。'),
 dict(file='13_候见倒厅与院落.md',id='SC13_DT',name='候见倒厅',place='通往王熙凤住处的候见与通报空间，包含倒厅、影壁旁及院门外。',space='等候处与内院之间有转折，影壁遮住部分视线。外面的人不能直接看到内室。',material='青砖地、灰墙影壁、木门框、素色帘。',light='院中天光与倒厅阴影相邻，转过影壁才看到另一片亮处。',sound=['往来脚步','门帘轻响','隔院不清楚的说话声'],smell=['木器','少量炭火'],temp='廊下避风，院中较凉。',anchors=[('倒厅外','来客到达，能看见等候处。','outer',3),('等候位','停留等消息，不能据远处动静编造内室谈话。','outer',3),('影壁旁','转折处，视线被墙遮挡。','turn',2),('院门外','通报返回时会经过，可向来客交代答复。','edge',3),('院内廊下','获准后进入，仍不是正房内室。','court',3),('回话近位','两个人相邻站立，低语只向近旁听众开放。','edge',2)],people='刘姥姥、板儿、周瑞妻子；平儿和通报丫鬟仅在实际进入后列为在场',opening='影壁截住了院内的视线，脚步声却从墙后传来。倒厅里留着几处空位，来客只能先看见院门。',tensions=['离主事的人已经很近，能知道的消息却仍然有限。','等候使人停住，通报的人不断进出。','礼数让出入有序，也可能让一句询问迟迟到不了对方耳边。'],scenario='通报是否发出、是否获准、谁已进入内院由状态记录。没有许可时停在相应等候位；不能默认主人拒见或接见。',exits=[('SC12_ZRZ','原路返回','可以选择离开'),('SC14_FJZF','院门与正房门','需要通行条件已满足')],props=['影壁','院门','廊柱','门帘','等候凳'],triggers=[('人物绕过影壁','更新可见范围，不公开墙后已经发生的对话'),('通报者回到等候位','只允许转述其实际收到的消息，不自动创造答复')],palette='青灰砖与木赭色，内院亮而外廊暗；不直接铺陈正房家具。'),
 dict(file='14_王熙凤正房.md',id='SC14_FJZF',name='凤姐正房',place='王熙凤住处的堂屋与相连房间，既待客也处理家事。',space='堂屋连接候见东间与会客处，门帘和房间转折使视线、听觉不完全相通。',material='砖地、木炕沿、漆木器、织物门帘与坐褥。',light='窗光落在炕沿，帘后较暗；器物只在入镜或被使用时点明。',sound=['自鸣钟机声','茶盘与碗盏','帘外脚步'],smell=['茶水','手炉炭火'],temp='屋内较暖，开帘时会带入冷气。',anchors=[('正房门外','候传或通报，不能默认听清所有内室话。','outer',3),('堂屋','连接两边房间，脚步可被邻近人听到。','hall',4),('东间候客位','可等候或用饭，桌子须存在才可使用。','east',3),('会客炕前','来客与主事者答话，身份不自动决定每句回应。','reception',3),('主事者位置','王熙凤处理来访与家事，未在场时保持空位。','reception',1),('侍立与递茶位','平儿等候、递茶和进退的位置。','reception',2),('帘边低语处','两名角色靠近后可私下交代，仍按声区和距离判定听众。','hall',2)],people='当前由上下文决定；可包括王熙凤、平儿、刘姥姥、板儿、周瑞妻子，贾蓉须实际入场后才在场',opening='堂屋里的钟机轻轻作响，门帘把两边的光隔开。炕前有一片可以站人的空处，茶盘留在近旁。',tensions=['陈设让人注意规矩，日常家务却不断打断体面。','主人能作决定，也要同时应对不同人的请求。','同屋并不等于同席，近处的低语也不等于所有人都听见。'],scenario='主人是否在场、来访目的、许可与已发生答复全由上下文写入。不预设给银、借物、用饭或辞客的结果。',exits=[('SC13_DT','正房门与院落','按实际告退或通行状态离开')],props=['门帘','炕沿','坐褥','茶盘','茶碗','手炉','自鸣钟','可搬动餐桌'],triggers=[('钟机实际到达报时状态','钟响；由人物自行决定是否回应'),('有人掀帘','更新门帘遮挡与可听范围'),('有人提出请求','记录请求对象和内容，不自动批准或拒绝')],palette='青绿与木赭为底，织物可少量暗红；不以满屏金色替代家具关系。')
]
