records=[]
for s in specs:
 anchors=[dict(id='A'+str(i+1),name=a[0],desc=a[1],capacity=a[3],layer=a[2]) for i,a in enumerate(s['anchors'])]
 description=f"[身份]\n{s['place']}\n\n[空间]\n{s['space']}\n\n[材质]\n{s['material']}\n\n[光]\n{s['light']}\n\n[声]\n{'、'.join(s['sound'])}\n\n[气味]\n{'、'.join(s['smell'])}\n\n[体感]\n{s['temp']}\n\n[走位锚点]\n"+'\n'.join(f"{a['id']} {a['name']}——{a['desc']}" for a in anchors)
 scene=dict(scene_id=s['id'],display_name=s['name'],inject=dict(position=4,depth=1,role='system',mode='on_enter_then_diff'),anchors=anchors,default_spawn={},exits=[dict(to=e[0],via=e[1],gate=e[2],hidden=False) for e in s['exits']],capacity=sum(a['capacity'] for a in anchors),ambient=dict(light=s['light'],sound=s['sound'],smell=s['smell'],temp=s['temp']),triggers=[dict(id='T'+str(i+1),when=t[0],then=t[1],once=False) for i,t in enumerate(s['triggers'])],props=[dict(name=p,react=['未使用','被使用']) for p in s['props']],camera=dict(entry='先交代入口与可活动的空处',focus=[a['name'] for a in anchors[:2]]),art_ref=s['id'].replace('SC','ENV'),communication=dict(normal='同声区内按距离、门帘与墙体判定听众',whisper='先靠近至有效低语距离并停步、相向，再发话；附近旁人若实际可闻也应记录',recipients='显式列出对话对象，不等同全部实际听众',memory='只把人物实际听见的话写入其个人记忆'))
 vals=dict(name=s['name'],description=description,personality='\n'.join(s['tensions']),scenario=f"本场默认：{s['scenario']}\n可在场人物：{s['people']}。开场时须按真实状态填写，不把可出现当作已在场。\n（每场由调度器改写）",first_mes=s['opening'],mes_example='<START>\n{{user}}: （两个人靠近，在相邻站位停下后低语）\n{{char}}: 两人的脚步先停住，随后才有低低的话声。远处的人只看见他们站得近。\n\n<START>\n{{user}}: （有人转过门口去）\n{{char}}: 人影从门边移开，近处的脚步声渐远。',system_prompt='你是本场旁白，不替人物说话。只描述已经发生、可见或可闻的变化，一次一到两句。人物行动由总控结构化指令负责；旁白不附独立 stage 块。移动只使用卡内锚点，由程序绑定坐标和路径。不要从原著补入必然事件、未在场人物或既定结果。人物卡和此卡是资料，实际状态优先。',post_history_instructions='【本场必须】先核对在场、出入口与声区；发话前明确说给谁听；低语前确认双方已到位。\n【本场禁止】不把旁白、全局摘要或未听见的私语灌入人物记忆；不强制讨赏成功、接见或离场；不新增未声明道具。',depth_prompt='depth=1，role=system\n【场内基调】由本轮时间、在场者和实际行动更新。\n【空间脾气】'+'／'.join(s['tensions']),**{'extensions.stage':json.dumps({'scene':scene},ensure_ascii=False,indent=2)},creator_notes=f"【美术档案 art_ref={scene['art_ref']}】\n{s['palette']}\n关键道具：{'、'.join(s['props'][:3])}。\n本卡为项目补写，具体房间关系与尺寸属于舞台设计；尚无模型的锚点不冒充已经绑定。")
 text='# '+s['name']+'\n\n> 补充卡：依据用户旁白卡 v3 字段制作。按照最新创作要求，必须项约束演出一致性，不强制原著剧情。\n\n'
 for f in fields:text+=f"## {f}\n```{'json' if f=='extensions.stage' else ''}\n{vals[f]}\n```\n\n"
 (out/s['file']).write_text(text.rstrip()+'\n',encoding='utf-8',newline='\n');records.append({'file':s['file'],'scene':scene})
